'use strict';
function actBossLabel(n){return n.trueBoss?L('True Final Boss','True Final Boss'):JourneyActs.act(S)===3?L('Final Boss','Boss final'):L('Map Boss','Boss do mapa');}
const actsRender=render;render=function(){JourneyActs.ensure(S);return actsRender();};
const actsResult=resultView;resultView=function(){if(S?.phase!=='actComplete')return actsResult();const a=JourneyActs.act(S),last=S.journey.history.at(-1),order=last?.order;show('<section class="act-result"><div class="eyebrow">'+L('MAP CLEARED','MAPA CONCLUÍDO')+'</div><h2>'+L('Map ','Mapa ')+a+'/3</h2><div class="act-victory-emblem">'+(order?orderMark(order):Icon('crown'))+'</div><div class="bigscore">'+S.score[0]+' : '+S.score[1]+'</div><div class="act-summary"><div><b>'+S.cards.length+'</b><span>'+L('Cards','Cartas')+'</span></div><div><b>'+S.gold+'</b><span>'+L('Gold','Ouro')+'</span></div><div><b>'+Progress.earned(S)+'</b><span>'+L('Diamonds earned','Diamantes acumulados')+'</span></div></div>'+damageReport()+'<div class="training-sticky">'+metaButton('advance-act',L('Continue to map ','Avançar ao mapa ')+(a+1),'','primary')+metaButton('home',L('Main menu','Menu principal'))+'</div></section>');};
const actsGuard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]');if(e.type==='click'&&el?.dataset.act==='advance-act'){e.preventDefault();e.stopImmediatePropagation();if(JourneyActs.advance(S)){battle=null;runRaidPending=null;save();render();}return true;}return actsGuard(e);};
const actsMapNode=mapNode;mapNode=function(id){const n=G.available(S).find(n=>n.id===id);if(!n||n.type!=='boss'||!n.campaign||n.campaign==='monsters')return actsMapNode(id);openModal('<div class="eyebrow">'+actBossLabel(n)+'</div><div class="node-preview-symbol blackfang-emblem">'+orderMark(n.campaign)+'</div><h2>'+L(n.campaign==='blackfang'?'Goblin King':'High Elf Harpist',n.campaign==='blackfang'?'Rei Goblin':'Harpista Alta Elfa')+'</h2><p>'+L('Win four rounds.','Vença quatro rodadas.')+'</p>'+metaButton('enter-node',L('Fight','Combater'),'data-id="'+n.id+'"','primary'));};
mapView=function(){JourneyActs.ensure(S);for(const n of S.map.flat())if(!S.route.includes(n.id))G.prepareRouteNode(S,n);const a=JourneyActs.act(S),height=1390,y=i=>height-60-i*91,map=S.map,available=new Set(G.available(S).map(n=>n.id));let paths='';for(let layer=0;layer<14;layer++)for(const n of map[layer])for(const id of n.links){const next=map[layer+1].find(t=>t.id===id);if(!next)continue;const visited=S.route.includes(n.id)&&S.route.includes(id),reachable=S.route.at(-1)===n.id&&available.has(id);paths+='<path d="M'+n.x*430+' '+y(layer)+' C'+n.x*430+' '+(y(layer)-45)+','+next.x*430+' '+(y(layer+1)+45)+','+next.x*430+' '+y(layer+1)+'" stroke="'+(visited?'#f0d18a':reachable?'#ffe3a3':'#a2c1bc')+'" opacity="'+(visited||reachable?1:.5)+'" stroke-width="'+(visited?4:reachable?3:2)+'" stroke-dasharray="'+(visited?'0':'4 6')+'" fill="none"/>';}
 const counts=JourneyActs.orderTotals(S),qualifying=a===3&&S.journey?.history.length===2&&S.journey.history[0].order===S.journey.history[1].order?S.journey.history[0].order:null,routeCounts=Object.entries(counts).map(([order,n])=>'<button data-act="order-history" data-id="'+order+'" class="order-counter '+(order===qualifying?'true-route':'')+'" title="'+(order===qualifying?'True Final Boss · ':'')+order+'" aria-label="'+(order===qualifying?'True Final Boss · ':'')+order+' '+n+'/6">'+orderMark(order)+'<b>'+n+'/6</b>'+(order===qualifying?Icon('crown'):'')+'</button>').join('');
 const nodes=map.flatMap((row,layer)=>row.map(n=>{const label=(n.type==='boss'?actBossLabel(n)+' · ':'')+(n.campaign==='monsters'?L(JourneyRaid.SPECS[n.raidKind||'tree'].en,JourneyRaid.SPECS[n.raidKind||'tree'].pt):n.campaign||mapType(n.type));return '<button class="map-node '+(available.has(n.id)?'available ':'')+(S.route.includes(n.id)?'visited ':'')+(n.trueBoss?'true-boss ':'')+n.type+(n.campaign==='blackfang'?' blackfang-node':n.campaign==='dawncrest'?' dawncrest-node':'')+'" style="left:'+n.x*100+'%;top:'+y(layer)+'px" data-act="node" data-id="'+n.id+'" '+(!available.has(n.id)?'disabled':'')+' aria-label="'+L('Layer ','Camada ')+(layer+1)+', '+esc(label)+'"><span class="symbol">'+nodeSymbol(n)+'</span></button>'; })).join('');
 show('<section class="journey-map-screen act-map act-'+a+'"><div class="map-toolbar"><div class="act-map-heading"><b>'+L('Map ','Mapa ')+a+'/3</b><small>'+L('Layer ','Camada ')+Math.min(15,S.layer+1)+'/15</small></div><span class="currency">◈ '+S.gold+'</span>'+miniAction('map-legend','question',L('Map legend','Legenda do mapa'))+miniAction('deck','deck',L('View deck','Ver baralho'))+miniAction('artifacts','star',L('Relics','Relíquias'))+'</div><div class="act-route-counts">'+routeCounts+'</div><div class="act-map-scroll" tabindex="0" aria-label="'+L('Map paths','Caminhos do mapa')+'"><div class="journey-map" style="height:'+height+'px"><div class="map-landscape"></div><svg class="journey-paths" viewBox="0 0 430 '+height+'" preserveAspectRatio="none">'+paths+'</svg>'+nodes+'</div></div></section>');const screen=$('screen-content');screen.classList.add('act-map-host');setTimeout(()=>{const scroller=document.querySelector('.act-map-scroll'),node=document.querySelector('.journey-map .available');if(scroller&&node)scroller.scrollTop=Math.max(0,node.offsetTop-scroller.clientHeight*.65);},0);
};
// Keep the map identifier visible during preparation and combat without adding a new HUD row.
const actsStatus=arenaStatus;arenaStatus=function(combat=false){const html=actsStatus(combat);if(!S||S.training||S.tutorialReplay)return html;return html.replace(/<span>R(\d+)<\/span>/,'<span>M'+JourneyActs.act(S)+' · R$1</span>');};

const actsLegend=mapLegend;mapLegend=function(){actsLegend();document.querySelector('#overlay>.modal')?.insertAdjacentHTML('beforeend','<p>'+L('Ironbound: if no other order qualifies, face one of its seven leaders. Defeat Ironbound bosses in all three maps to reveal the First Wayfarer on map 3.','Ironbound: se nenhuma outra ordem cumprir sua condição, enfrente um dos sete líderes. Derrote bosses da Ironbound nos três mapas para revelar o Primeiro Viajante no mapa 3.')+'</p>');document.querySelector('#overlay>.modal')?.insertAdjacentHTML('beforeend','<p>'+L('True Final Boss: defeat the same order’s Boss in maps 1 and 2, then win both encounters of that order in map 3.','True Final Boss: derrote o Boss da mesma ordem nos mapas 1 e 2 e vença os dois encontros dessa ordem no mapa 3.')+'</p>');const modal=document.querySelector('#overlay>.modal');if(modal){modal.classList.add('act-map-legend');const content=document.createElement('div');content.className='act-legend-scroll';for(const child of [...modal.children])if(!child.matches('.close,h2'))content.appendChild(child);modal.appendChild(content);}};
